package com.smartmart.order.controller; import com.smartmart.order.dto.OrderResponse; import com.smartmart.order.service.OrderService; import com.smartmart.user.entity.*; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") @RequiredArgsConstructor public class OrderController{private final OrderService s;@GetMapping public List<OrderResponse> list(@AuthenticationPrincipal User u){return u.getRole()==Role.MANAGER?s.all():s.history(u);}@GetMapping("/{id}") public OrderResponse one(@AuthenticationPrincipal User u,@PathVariable Long id){return s.find(u,id,u.getRole()==Role.MANAGER);}}
